from common import Q
W="awliya"
Q(W,1,"Tasawwuf is the science of which level of the religion described in the Hadith of Jibril?","Ihsan",["Islam","Iman","Qadar"],"Ihsan — worshipping Allah as though you see Him — is the heart of tasawwuf.","Sahih Muslim 8")
Q(W,1,"Shaykh Abdul Qadir al-Jilani is buried in which city?","Baghdad",["Damascus","Ajmer","Konya"],"Ghawth al-A'zam Shaykh Abdul Qadir al-Jilani (d. 561 AH) taught and is buried in Baghdad.","Qala'id al-Jawahir")
Q(W,1,"Which Sufi order is named after Shaykh Abdul Qadir al-Jilani?","Qadiriyyah",["Chishtiyyah","Naqshbandiyyah","Shadhiliyyah"],"The Qadiri path traces to him and spread across the Muslim world.","Qala'id al-Jawahir")
Q(W,1,"Khwaja Mu'in ad-Din Chishti, 'Gharib Nawaz', is buried in…","Ajmer",["Delhi","Lahore","Pakpattan"],"He came to India in the 12th century; his dargah is in Ajmer Sharif.","Siyar al-Awliya")
Q(W,2,"Data Ganj Bakhsh Ali al-Hujwiri wrote which classic of tasawwuf?","Kashf al-Mahjub",["Ihya Ulum ad-Din","Al-Hikam","Masnavi"],"Kashf al-Mahjub is among the earliest Persian works on tasawwuf; he is buried in Lahore.","Kashf al-Mahjub")
Q(W,2,"Which Sufi order is named after Shaykh Baha' ad-Din of Bukhara?","Naqshbandiyyah",["Suhrawardiyyah","Rifa'iyyah","Qadiriyyah"],"Shaykh Baha' ad-Din Naqshband (d. 791 AH) gave the order its name.","Rashahat Ayn al-Hayat")
Q(W,1,"Which scholar is called 'Hujjat al-Islam' and wrote 'Ihya Ulum ad-Din'?","Imam al-Ghazali",["Imam ar-Razi","Imam al-Qushayri","Imam as-Suyuti"],"Imam Abu Hamid al-Ghazali (d. 505 AH) united fiqh, creed and tasawwuf in the Ihya.","Tabaqat ash-Shafi'iyyah al-Kubra")
Q(W,2,"Which early Sufi is called 'Sayyid at-Ta'ifah' (master of the group)?","Imam al-Junayd al-Baghdadi",["Abu Yazid al-Bistami","Ma'ruf al-Karkhi","Sari as-Saqati"],"Al-Junayd said: 'Our path is bound by the Quran and the Sunnah.'","Ar-Risalah al-Qushayriyyah")
Q(W,2,"Rabi'ah al-Adawiyyah, known for her pure love of Allah, lived in which city?","Basra",["Kufa","Baghdad","Cairo"],"She was a renowned worshipper of Basra in the 2nd century AH.","Ar-Risalah al-Qushayriyyah")
Q(W,2,"Hasan al-Basri belonged to which generation?","The Tabi'in (Successors)",["The Companions","The later Ottomans","The Mughal era"],"Hasan al-Basri (d. 110 AH) met many Companions and is a pillar of early zuhd.","Siyar A'lam an-Nubala")
Q(W,2,"'Awarif al-Ma'arif' was written by the founder of which order?","Suhrawardiyyah",["Chishtiyyah","Qadiriyyah","Naqshbandiyyah"],"Shaykh Shihab ad-Din Umar as-Suhrawardi (d. 632 AH) wrote it.","Awarif al-Ma'arif")
Q(W,1,"Hazrat Nizam ad-Din Awliya, 'Mahbub-e-Ilahi', is buried in…","Delhi",["Ajmer","Multan","Hyderabad"],"His dargah is in Nizamuddin, Delhi; Amir Khusrau was his disciple.","Fawa'id al-Fu'ad")
Q(W,2,"Baba Farid ad-Din Ganj-e-Shakar is buried in…","Pakpattan",["Ajmer","Sirhind","Delhi"],"A great Chishti shaykh, the teacher of Nizam ad-Din Awliya.","Siyar al-Awliya")
Q(W,3,"Khwaja Qutb ad-Din Bakhtiyar Kaki, successor of Khwaja Gharib Nawaz, is buried in…","Mehrauli, Delhi",["Ajmer","Pakpattan","Gulbarga"],"The Qutub Minar area is named in his honour.","Siyar al-Awliya")
Q(W,2,"Who is known as 'Mujaddid Alf Thani' (Renewer of the second millennium)?","Imam Ahmad Sirhindi",["Shah Waliullah","Imam al-Ghazali","Shaykh Abdul Haqq Dehlawi"],"Imam Rabbani Ahmad Sirhindi (d. 1034 AH) of the Naqshbandi order, author of the Maktubat.","Maktubat Imam Rabbani")
Q(W,2,"Shah Waliullah Muhaddith Dehlawi wrote which famous book?","Hujjat Allah al-Balighah",["Kashf al-Mahjub","Futuh al-Ghayb","Al-Hikam"],"He was a great muhaddith and Sufi of Delhi (d. 1176 AH).","Hujjat Allah al-Balighah")
Q(W,1,"Mawlana Jalal ad-Din Rumi wrote which famous poem?","The Masnavi",["The Burdah","Gulistan","Diwan-e-Hafiz"],"Rumi is buried in Konya; his Masnavi is a vast poem of spiritual teaching.","Masnavi-ye Ma'navi")
Q(W,2,"Who wrote 'ar-Risalah', a foundational manual of tasawwuf?","Imam Abu al-Qasim al-Qushayri",["Imam an-Nawawi","Imam al-Bukhari","Ibn Khaldun"],"Al-Qushayri (d. 465 AH) wrote it to show tasawwuf's roots in the Quran, Sunnah and sound creed.","Ar-Risalah al-Qushayriyyah")
Q(W,2,"Which Sufi order is named after Shaykh Abu al-Hasan ash-Shadhili?","Shadhiliyyah",["Tijaniyyah","Rifa'iyyah","Chishtiyyah"],"Shaykh ash-Shadhili (d. 656 AH) taught in North Africa and Egypt.","Lata'if al-Minan")
Q(W,2,"Who wrote 'al-Hikam', the famous aphorisms of tasawwuf?","Ibn Ata'illah al-Iskandari",["Ibn Arabi","Imam al-Ghazali","Ali al-Hujwiri"],"A Shadhili master of Alexandria (d. 709 AH).","Al-Hikam al-Ata'iyyah")
Q(W,2,"Which order traces to Sayyid Ahmad ar-Rifa'i of Iraq?","Rifa'iyyah",["Qadiriyyah","Mawlawiyyah","Suhrawardiyyah"],"Sayyid Ahmad al-Kabir ar-Rifa'i (d. 578 AH) was known for his humility.","Tabaqat al-Awliya")
Q(W,2,"The Prophet ﷺ told Umar about a man from Yemen whose dua is accepted. Who was he?","Uways al-Qarani",["Salman al-Farisi","Abu Dharr","Hasan al-Basri"],"He was devoted to his mother; the Prophet ﷺ told Umar to ask him for forgiveness.","Sahih Muslim 2542")
Q(W,2,"Khwaja Bandanawaz Gesudaraz is buried in which city?","Gulbarga (Kalaburagi)",["Hyderabad","Bidar","Delhi"],"A Chishti master (d. 825 AH) who brought the Chishti path to the Deccan.","Siyar al-Awliya")
Q(W,3,"'Futuh al-Ghayb' is a collection of discourses by…","Shaykh Abdul Qadir al-Jilani",["Shaykh Ahmad Sirhindi","Imam al-Qushayri","Rumi"],"It contains his talks on tawhid, trust and surrender to Allah.","Futuh al-Ghayb")
Q(W,1,"What does 'dhikr' mean?","Remembrance of Allah",["Fasting","Travel","Charity"],"'Truly, in the remembrance of Allah do hearts find rest.'","Quran 13:28")
Q(W,2,"What does 'tazkiyat an-nafs' mean?","Purification of the soul",["Learning Arabic","Building masjids","Memorising hadith"],"'He has succeeded who purifies it.'","Quran 91:9")
Q(W,2,"A 'silsilah' in tasawwuf is…","the chain of spiritual teachers back to the Prophet ﷺ",["a type of prayer bead","a book of poems","a Sufi hat"],"Each order's silsilah connects its shaykhs, link by link, to the Prophet ﷺ.","Ar-Risalah al-Qushayriyyah")
Q(W,2,"The pledge (bay'ah) given to a shaykh follows which practice in the Quran?","The pledge the Companions gave the Prophet ﷺ",["The pledge of the kings","The oath of Iblis","A pre-Islamic custom only"],"'Indeed those who pledge allegiance to you, pledge allegiance to Allah.'","Quran 48:10; 48:18")
Q(W,2,"The 'nafs al-mutma'innah' is…","the soul at peace",["the soul that commands evil","the self-blaming soul","the animal soul"],"'O soul at peace, return to your Lord, well-pleased and pleasing.'","Quran 89:27–28")
Q(W,2,"The 'nafs al-ammarah' is…","the soul that commands evil",["the soul at peace","the self-blaming soul","the soul of the prophets"],"Yusuf said: 'The soul is surely a commander of evil, except where my Lord has mercy.'","Quran 12:53")
Q(W,2,"In a Hadith Qudsi, Allah declares war on whoever shows enmity to…","His wali (friend)",["the poor","the scholars only","the angels"],"'Whoever shows enmity to a wali of Mine, I declare war on him.'","Sahih al-Bukhari 6502")
Q(W,1,"What does the Quran say about the awliya of Allah?","No fear shall be on them, nor shall they grieve",["They never pray","They are angels","They know the Unseen fully"],"'Surely the friends of Allah — no fear shall be on them nor shall they grieve: those who believe and are mindful of Him.'","Quran 10:62–63")
Q(W,2,"In the subcontinent, what does 'urs' commemorate?","The anniversary of a wali's passing (wisal)",["A wedding","Eid","The new year"],"It marks the day the wali met his Lord, with Quran, dhikr and remembrance.","Siyar al-Awliya")
Q(W,3,"Makhdum Ali Mahimi, the scholar-saint of Mahim, was from which coast?","Konkan (Mumbai)",["Malabar","Coromandel","Gujarat"],"Makhdum Ali al-Mahimi (d. 835 AH) wrote the tafsir Tabsir ar-Rahman.","Tabsir ar-Rahman")

D="duas"
Q(D,1,"What do we say before eating?","Bismillah",["Alhamdulillah","Subhan Allah","Allahu Akbar"],"The Prophet ﷺ told a boy: 'Say Bismillah, eat with your right hand, and eat from what is near you.'","Sahih al-Bukhari 5376")
Q(D,2,"If you forget Bismillah at the start of a meal, what do you say?","Bismillahi awwalahu wa akhirahu",["Astaghfirullah","Inna lillah","Ma sha Allah"],"'In the name of Allah at its beginning and its end.'","Sunan Abi Dawud 3767; at-Tirmidhi 1858")
Q(D,1,"What do we say when we sneeze?","Alhamdulillah",["Bismillah","Subhan Allah","Allahu Akbar"],"The one who hears replies 'Yarhamuk Allah', and the sneezer answers 'Yahdikumullah wa yuslihu balakum'.","Sahih al-Bukhari 6224")
Q(D,2,"Which dua is said before entering the toilet?","Allahumma inni a'udhu bika minal-khubuthi wal-khaba'ith",["Allahumma iftah li abwaba rahmatik","Ghufranak","Rabbi zidni 'ilma"],"'O Allah, I seek refuge in You from the male and female devils.'","Sahih al-Bukhari 142")
Q(D,2,"What is said on leaving the toilet?","Ghufranak (I seek Your forgiveness)",["Bismillah","Alhamdulillah only","Allahu Akbar"],"The Prophet ﷺ would say 'Ghufranak' on coming out.","Sunan Abi Dawud 30; at-Tirmidhi 7")
Q(D,1,"Which dua is said before sleeping?","Bismika Allahumma amutu wa ahya",["Subhanal-ladhi sakhkhara lana hadha","Allahumma barik lana","Rabbana atina"],"'In Your name, O Allah, I die and I live.'","Sahih al-Bukhari 6324")
Q(D,2,"On waking up, the Prophet ﷺ would praise Allah who…","gave us life after He caused us to die, and to Him is the return",["fed us and gave us drink","made us Muslims","created the heavens"],"'Alhamdulillahil-ladhi ahyana ba'da ma amatana wa ilayhin-nushur.'","Sahih al-Bukhari 6324")
Q(D,1,"Which dua is said on entering the masjid?","Allahumma iftah li abwaba rahmatik",["Allahumma inni as'aluka min fadlik","Ghufranak","Hasbunallah"],"'O Allah, open for me the doors of Your mercy.'","Sahih Muslim 713")
Q(D,2,"Which dua is said on leaving the masjid?","Allahumma inni as'aluka min fadlik",["Allahumma iftah li abwaba rahmatik","Bismika amutu","Rabbi zidni 'ilma"],"'O Allah, I ask You of Your bounty.'","Sahih Muslim 713")
Q(D,1,"Which dua did the Prophet ﷺ make most often?","Rabbana atina fid-dunya hasanah…",["Rabbi zidni 'ilma","La hawla wa la quwwata illa billah","Hasbunallah"],"'Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.'","Quran 2:201; Sahih al-Bukhari 6389")
Q(D,2,"Whose dua was 'La ilaha illa anta, subhanaka, inni kuntu minaz-zalimin'?","Prophet Yunus",["Prophet Adam","Prophet Musa","Prophet Ayyub"],"He called with it from inside the fish; any Muslim who calls with it is answered.","Quran 21:87; Sunan at-Tirmidhi 3505")
Q(D,1,"Which is the Quranic dua for parents?","Rabbir-hamhuma kama rabbayani saghira",["Rabbi zidni 'ilma","Rabbish-rah li sadri","Rabbana zalamna anfusana"],"'My Lord, have mercy on them as they raised me when I was small.'","Quran 17:24")
Q(D,1,"Which is the Quranic dua for increase in knowledge?","Rabbi zidni 'ilma",["Rabbana atina","Hasbiyallah","Rabbi-ghfir li"],"'My Lord, increase me in knowledge.'","Quran 20:114")
Q(D,2,"What is the 'Sayyid al-Istighfar' (master of seeking forgiveness)?","Allahumma anta Rabbi, la ilaha illa ant, khalaqtani…",["Astaghfirullah wa atubu ilayh only","Subhanallahi wa bihamdihi","La hawla wa la quwwata illa billah"],"Whoever says it with conviction in the day and dies before evening is of the people of Paradise.","Sahih al-Bukhari 6306")
Q(D,2,"Which dua did the Prophet ﷺ teach Aishah for Laylat al-Qadr?","Allahumma innaka 'afuwwun tuhibbul-'afwa fa'fu 'anni",["Rabbana atina","Allahumma barik lana","Rabbi-shrah li sadri"],"'O Allah, You are Pardoning and love to pardon, so pardon me.'","Sunan at-Tirmidhi 3513")
Q(D,2,"Ibrahim said 'Hasbunallahu wa ni'mal-wakil' when…","he was thrown into the fire",["he built the Kaaba","he left Hajar in Makkah","he saw the stars"],"'Allah is sufficient for us, and He is the best Disposer of affairs.'","Sahih al-Bukhari 4563; Quran 3:173")
Q(D,2,"Which dua is recited when setting off on a journey?","Subhanal-ladhi sakhkhara lana hadha…",["Bismika amutu","Allahumma iftah li","Ghufranak"],"'Glory be to Him who has subjected this to us, and we could not have done it ourselves.'","Quran 43:13–14; Sahih Muslim 1342")
Q(D,2,"What did the Prophet ﷺ say when visiting the sick?","La ba'sa, tahurun in sha Allah",["Inna lillah","Ma sha Allah","Jazak Allah"],"'No harm, it is a purification, if Allah wills.'","Sahih al-Bukhari 3616")
Q(D,1,"What is said when leaving home?","Bismillahi tawakkaltu 'alallah, la hawla wa la quwwata illa billah",["Bismika amutu wa ahya","Allahumma iftah li abwaba rahmatik","Ghufranak"],"The one who says it is guided, sufficed and protected.","Sunan Abi Dawud 5095; at-Tirmidhi 3426")
Q(D,2,"Which dua did the Prophet ﷺ say on breaking the fast?","Dhahabaz-zama'u wabtallatil-'uruq wa thabatal-ajru in sha Allah",["Rabbi zidni 'ilma","Allahumma iftah li","Hasbunallah"],"'The thirst is gone, the veins are moistened, and the reward is confirmed, if Allah wills.'","Sunan Abi Dawud 2357")
Q(D,3,"What is said on seeing the new crescent moon?","Allahumma ahillahu 'alayna bil-yumni wal-iman…",["Allahumma sayyiban nafi'a","Subhanal-ladhi sakhkhara","La ba'sa tahur"],"'O Allah, bring it over us with blessing and faith, safety and Islam. My Lord and your Lord is Allah.'","Sunan at-Tirmidhi 3451")
Q(D,2,"What did the Prophet ﷺ say when it rained?","Allahumma sayyiban nafi'a",["Allahumma ahillahu","Ghufranak","Bismillah"],"'O Allah, (make it) a beneficial rain.'","Sahih al-Bukhari 1032")
Q(D,1,"What should we say when we feel angry?","A'udhu billahi minash-shaytanir-rajim",["Alhamdulillah","Ma sha Allah","Jazak Allah"],"The Prophet ﷺ said that saying it would take away the anger.","Sahih al-Bukhari 3282")
Q(D,1,"What do we say when a calamity strikes?","Inna lillahi wa inna ilayhi raji'un",["Ma sha Allah","Subhan Allah","Bismillah"],"'Indeed we belong to Allah and to Him we return' — then ask Allah for something better.","Quran 2:156; Sahih Muslim 918")
Q(D,2,"On which day did the Prophet ﷺ ask us to send abundant salawat on him?","Friday",["Monday","Thursday","Saturday"],"'Send abundant blessings on me on Friday, for they are presented to me.'","Sunan Abi Dawud 1047")
Q(D,2,"How many times is 'Bismillahil-ladhi la yadurru ma'asmihi shay'un…' recited morning and evening?","3",["1","7","10"],"Whoever says it three times, nothing will harm him.","Sunan Abi Dawud 5088; at-Tirmidhi 3388")
Q(D,1,"Which prophet prayed 'Rabbish-rah li sadri' (My Lord, expand my chest)?","Musa",["Isa","Nuh","Ibrahim"],"Musa asked for ease before going to Fir'awn.","Quran 20:25")
Q(D,2,"'Rabbana zalamna anfusana…' was the dua of whom?","Adam and Hawwa",["Nuh","Yunus","Ibrahim"],"'Our Lord, we have wronged ourselves; if You do not forgive us and have mercy on us, we will be among the losers.'","Quran 7:23")
Q(D,2,"Which Quranic dua asks for righteous spouses and children?","Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yun",["Rabbi zidni 'ilma","Rabbana atina","Rabbi-ghfir li"],"'…the coolness of our eyes, and make us leaders of the God-fearing.'","Quran 25:74")
Q(D,2,"Reciting which verse before sleeping keeps a guardian from Allah with you all night?","Ayat al-Kursi",["Al-Fatihah","The last verse of Al-Kahf","Surah Al-Asr"],"So the Prophet ﷺ confirmed in the story of Abu Hurayrah and the thief.","Sahih al-Bukhari 2311")
Q(D,2,"Which verses, recited at night, are 'sufficient' for a person?","The last two verses of Al-Baqarah",["The first ten of Al-Kahf","The last three surahs","Ayat an-Nur"],"'Whoever recites the last two verses of Surat al-Baqarah at night, they will suffice him.'","Sahih al-Bukhari 5009")
Q(D,1,"What should we do when we hear the adhan?","Repeat what the muezzin says",["Stay silent","Leave the room","Say Amin"],"Then send salawat and ask for al-Wasilah for the Prophet ﷺ.","Sahih al-Bukhari 611, 614")
Q(D,1,"What do we say when we see something we like?","Ma sha Allah, tabarak Allah",["Inna lillah","Astaghfirullah","A'udhu billah"],"Saying 'Ma sha Allah, la quwwata illa billah' and asking for barakah protects from the evil eye.","Quran 18:39; Sunan Ibn Majah 3509")
